PARAMS = ['Vmax','Km','Ki','f']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    frac = 1.0/(1+I/p['Ki'])
    base = p['Vmax']*S/((p['Km']+S))
    return base*(p['f'] + (1-p['f'])*frac)

